package android.media;import java.util.*;import android.graphics.Bitmap;public class MediaMetadata {public static final String METADATA_KEY_MEDIA_ID="id",METADATA_KEY_TITLE="title",METADATA_KEY_ARTIST="artist",METADATA_KEY_ALBUM="album",METADATA_KEY_DURATION="duration",METADATA_KEY_ALBUM_ART="art",METADATA_KEY_ART="art2";public final Map<String,Object> values=new HashMap<>();public String getString(String k){return (String)values.get(k);}public long getLong(String k){Object v=values.get(k);return v==null?0:(Long)v;}public Bitmap getBitmap(String k){return (Bitmap)values.get(k);}}
